insert into public.official_food_aliases (
  food_code, alias, reading, normalized, is_candidate, candidate_rank,
  note, source, is_group, priority
)
select distinct on (food_code, normalized)
  food_code,
  alias,
  reading,
  normalized,
  false,
  candidate_rank,
  note,
  source,
  false,
  priority
from (
  select
    v.food_code,
    v.alias,
    v.reading,
    public.normalize_food_search_text(v.alias) as normalized,
    v.candidate_rank,
    v.note,
