  ) as v(food_code, alias, reading, candidate_rank, note, source, priority)
) as incoming
where normalized <> ''
order by food_code, normalized, (source = 'colloquial_v1') desc, candidate_rank, priority
on conflict (food_code, normalized) do update set
  candidate_rank = excluded.candidate_rank,
  reading = excluded.reading
where excluded.source = 'colloquial_v1';


-- Group labels such as 豚肉 list every cut, including いのぶた.
update public.official_food_aliases
set candidate_rank = 90
where is_group
  and candidate_rank is null;

update public.official_foods as food
set reading_tokens = coalesce((
  select array_agg(distinct public.normalize_food_search_text(token))
  from pg_catalog.regexp_split_to_table(coalesce(food.reading, ''), ' ') as token
  where public.normalize_food_search_text(token) <> ''
), '{}');

update public.official_food_aliases as alias_row
set reading_tokens = coalesce((
  select array_agg(distinct public.normalize_food_search_text(token))
  from pg_catalog.regexp_split_to_table(coalesce(alias_row.reading, alias_row.alias), ' ') as token
  where public.normalize_food_search_text(token) <> ''
), '{}');

create index if not exists official_foods_reading_tokens_idx
  on public.official_foods using gin (reading_tokens);

create index if not exists official_food_aliases_reading_tokens_idx
  on public.official_food_aliases using gin (reading_tokens);

-- Kanji surfaces people also say in kana. Public foods have no composition-table
-- reading of their own, so a saved name is rewritten with these spellings.
create table if not exists public.food_search_spellings (
  surface text primary key,
  reading text not null
);

truncate public.food_search_spellings;

insert into public.food_search_spellings (surface, reading)
select distinct on (public.normalize_food_search_text(alias))
  public.normalize_food_search_text(alias),
  public.normalize_food_search_text(reading)
from public.official_food_aliases
where alias ~ '[一-龯]'
  and coalesce(reading, '') <> ''
  and public.normalize_food_search_text(alias)
      <> public.normalize_food_search_text(reading)
  and pg_catalog.char_length(alias) between 2 and 16
order by public.normalize_food_search_text(alias),
  case source
    when 'colloquial_v1' then 0
    when 'spoken_manual_v1' then 1
    when 'karonavi_spoken_seed_v1' then 2
    else 3
  end,
  candidate_rank nulls last,
  priority;

create or replace function public.expand_public_food_voice(p_name text)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_text text := public.normalize_food_search_text(coalesce(p_name, ''));
  rec record;
begin
  for rec in
    select surface, reading
    from public.food_search_spellings
    where pg_catalog.strpos(v_text, surface) > 0
    order by pg_catalog.char_length(surface) desc
  loop
    v_text := pg_catalog.replace(v_text, rec.surface, rec.reading);
  end loop;
  return v_text;
end;
$$;

revoke all on function public.expand_public_food_voice(text) from public, anon, authenticated;
revoke all on table public.food_search_spellings from public, anon, authenticated;

create or replace function public.saved_foods_fill_voice()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.voice_normalized := public.normalize_food_search_text(new.name);
  new.voice_reading := public.expand_public_food_voice(new.name);
  new.voice_katakana := public.hiragana_to_katakana(new.voice_reading);
  return new;
end;
$$;

revoke all on function public.saved_foods_fill_voice() from public, anon, authenticated;
grant execute on function public.saved_foods_fill_voice() to authenticated;

update public.saved_foods
set name = name;
